using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using OpenAI;

// Build configuration from appsettings.json and environment variables
var configuration = new ConfigurationBuilder()
    .AddJsonFile("appsettings.json", optional: true)
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value (or AI__ApiKey environment variable) to your OpenAI API key.");

var modelId = configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

// Set up DI and register the chat client
var services = new ServiceCollection();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

// Define tools the agent can use
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent with tool access
var researchAgent = chatClient.AsAIAgent(
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the web_search tool (perform multiple searches to cover different angles).
        2. Save key findings as notes using the save_note tool.
        3. Review your notes with get_notes, then provide a comprehensive summary of your research.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// Wrap in a LoopAgent so the agent can iterate (search → note → summarize)
var agent = new LoopAgent(
    researchAgent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 10 });

// Get the research topic from the user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var response = await agent.RunAsync($"Research the following topic and provide a summary: {topic}");

Console.WriteLine("═══ Research Summary ═══");
Console.WriteLine(response.Text);
Console.WriteLine($"\n[Token usage: {response.Usage?.InputTokenCount ?? 0} input, {response.Usage?.OutputTokenCount ?? 0} output]");

// --- Tool implementations ---

// In-memory note storage
List<string> notes = [];

[Description("Search the web for information on a query. Returns search result snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results — in production, integrate with a real search API (e.g., Bing Search)
    Console.WriteLine($"  🔍 Searching: {query}");
    return $"""
        Search results for "{query}":
        1. [Wikipedia] {query} - Overview article covering key concepts, history, and notable developments.
           Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
        2. [Research Paper] Recent advances in {query} - A 2024 survey paper discussing current state and future directions.
           Source: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}
        3. [News] Latest developments in {query} - News coverage of recent breakthroughs and industry applications.
           Source: https://news.example.com/{Uri.EscapeDataString(query)}
        """;
}

[Description("Save a research note for later reference.")]
string SaveNote(
    [Description("Title of the note")] string title,
    [Description("Content of the note")] string content)
{
    var note = $"[{title}]: {content}";
    notes.Add(note);
    Console.WriteLine($"  📝 Saved note: {title}");
    return $"Note saved: '{title}'";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📋 Retrieving {notes.Count} note(s)");
    return string.Join("\n\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

